import {captureCalculation,RELEASE} from './material-notebook.js?v=20261031-frontiers1';
import {esc,num,table,notes,sources,controlsHTML,readControls,resultHTML,bindResult} from './bridges-views.js?v=20261031-frontiers1';
import {renderResponseProjects} from './response-projects.js?v=20261031-frontiers1';
const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
const options=(rows,v)=>rows.map(([id,title])=>`<option value="${esc(id)}" ${String(id)===String(v)?'selected':''}>${esc(title)}</option>`).join('');
let catalogPromise,lastResult=null;
const catalog=()=>catalogPromise??=fetch('data/bridges-materials.json?v='+RELEASE).then(r=>{if(!r.ok)throw Error('多体谱、极化子与密度矩阵课程暂未载入');return r.json();}).catch(e=>{catalogPromise=null;throw e;});
export const getBridgesResult=()=>lastResult;
export const bridgesCourseRoute=(id,query='')=>'#classroom/'+({manybody:'observables',polaron:'structure-dynamics',density:'spin',workshop:'crystal'}[id]||'crystal')+'?module='+id+(query?'&'+query:'');
const select=(label,key,rows,value)=>`<label>${esc(label)}<select id="pw-${key}">${options(rows,value)}</select></label>`;

export async function renderBridgesView({container,selection={},run,cancelRun,download,onNavigate=()=>{},onLocation=()=>{}}){
 container.innerHTML='<div class="obs-page qm-page response-page bridges-page"><p role="status">正在准备多体谱、极化子与密度矩阵课程…</p></div>';
 const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;lastResult=null;
 let data;try{data=await catalog();}catch(e){if(current())root.innerHTML=`<p role="alert">${esc(e.message)}</p>`;return;}if(!current())return;
 let module=data.modules.find(m=>m.id===selection.module)||data.modules[0],lesson=data.lessons.find(l=>l.id===selection.lesson&&l.module===module.id)||data.lessons.find(l=>l.module===module.id),exercise=data.exercises.find(e=>e.id===selection.exercise&&e.module===module.id)||data.exercises.find(e=>e.lesson===lesson.id),tab=selection.calculationOnly?'lab':selection.atlasOnly?'cases':['learn','lab','derive','cases','project'].includes(selection.tab)?selection.tab:'learn';
 if(selection.exercise)lesson=data.lessons.find(l=>l.id===exercise.lesson)||lesson;
 const defaults=Object.fromEntries(data.modules.map(m=>[m.id,Object.fromEntries(m.fields.map(f=>[f.key,f.default]))]));
 const forms=structuredClone(defaults),material=data.cases.find(c=>c.id===selection.material&&c.module===module.id);let preset=selection.preset||material?.preset||'';
 const applyPreset=id=>{const p=module.presets.find(p=>p.id===id);if(p){forms[module.id]={...structuredClone(defaults[module.id]),...structuredClone(p.input)};if(p.input.data)forms[module.id].content=JSON.stringify(p.input.data,null,2);preset=p.id;}};applyPreset(preset);
 let result=null,busy=false,ticket=0,progress={},prediction=null,predicted=-1,predictionTime='',predictionReport=null;try{const p=JSON.parse(localStorage.getItem('symmetry-lab.bridges.progress.v1')||'{}');if(object(p))progress=p;}catch{}
 const sync=()=>onNavigate({module:module.id,tab,lesson:lesson.id,exercise:tab==='derive'?exercise.id:undefined,material:selection.material,preset});
 const context=()=>new URLSearchParams({module:module.id,...(selection.material?{material:selection.material}:{}),...(preset?{preset}:{})}).toString();
 const links=()=>`<div class="obs-links"><a href="${bridgesCourseRoute(module.id,(selection.material?'material='+encodeURIComponent(selection.material)+'&':'')+(preset?'preset='+encodeURIComponent(preset):''))}">课程与推导 →</a><a href="#atlas/bridges?${esc(context())}">材料与模型案例 →</a><a href="#atlas/projects?module=${module.id}">跨模块项目作业 →</a><a href="#atlas/notebook">保存材料研究记录 →</a></div>`;
 function invalidate(message='参数已改变，请运行计算以更新图形。'){ticket++;result=null;lastResult=null;prediction=null;predicted=-1;predictionReport=null;if(busy){cancelRun?.();busy=false;}if($('#pw-result'))$('#pw-result').innerHTML=`<p role="status">${esc(message)}</p>`;if($('#pw-run'))$('#pw-run').disabled=false;}
 function draw(){if(!current())return;onLocation((selection.calculationOnly?'计算中心 / ':selection.atlasOnly?'群与材料图谱 / ':'学习中心 / ')+module.title);root.innerHTML=`<header class="obs-header"><span class="obs-eyebrow">SPECTRA · POLARONS · QUANTUM STATES</span><h2>${selection.atlasOnly?'从对称约束到多体谱与量子动力学':esc(module.title)}</h2><p>${selection.atlasOnly?'真实材料背景与可验证教学模型相互连接。':esc(module.summary)}</p></header>${selection.calculationOnly||selection.atlasOnly?'':`<nav class="obs-tabs" aria-label="多体谱、极化子与密度矩阵课堂">${[['learn','课程讲解'],['lab','交互实验'],['derive','分步练习'],['cases','材料案例'],['project','项目作业']].map(([id,t])=>`<button type="button" data-pw-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${t}</button>`).join('')}</nav>`}<div id="pw-content"></div>`;root.querySelectorAll('[data-pw-tab]').forEach(b=>b.onclick=()=>{invalidate();tab=b.dataset.pwTab;draw();sync();});if(tab==='learn')learn();else if(tab==='derive')derive();else if(tab==='cases')cases();else if(tab==='project')renderResponseProjects({container:$('#pw-content'),selection:{project:selection.project,module:module.id},download});else lab();}
 function learn(){$('#pw-content').innerHTML=`${select('选择主题','lesson',data.lessons.filter(l=>l.module===module.id).map(l=>[l.id,l.title]),lesson.id)}<article class="obs-lesson"><h2>${esc(lesson.title)}</h2><p class="obs-lead">${esc(lesson.summary)}</p>${lesson.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.formula?`<div class="obs-formula">${esc(s.formula)}</div>`:''}</section>`).join('')}<div class="obs-links"><button id="pw-to-lab" class="primary">打开对应实验 →</button><button id="pw-to-derive" class="secondary">分步推导 →</button></div>${links()}${sources(data.sources.filter(s=>lesson.references.includes(s.id)))}</article>`;$('#pw-lesson').onchange=e=>{lesson=data.lessons.find(l=>l.id===e.target.value);exercise=data.exercises.find(e=>e.lesson===lesson.id);draw();sync();};$('#pw-to-lab').onclick=()=>{applyPreset(lesson.preset);invalidate();tab='lab';draw();sync();};$('#pw-to-derive').onclick=()=>{exercise=data.exercises.find(e=>e.lesson===lesson.id);tab='derive';draw();sync();};}
 function cases(){$('#pw-content').innerHTML=`<div class="obs-case-grid">${data.cases.filter(c=>selection.atlasOnly||c.module===module.id).sort((a,b)=>(b.id===selection.material)-(a.id===selection.material)).map(c=>{const m=data.modules.find(m=>m.id===c.module),q=new URLSearchParams({material:c.id,preset:c.preset}).toString();return `<article><span class="obs-eyebrow">${esc(c.kind)}</span><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p>${notes([c.assumption])}<div class="obs-links"><a href="${bridgesCourseRoute(c.module,q)}">学习与推导 →</a><a href="#compute/${m.route}?${q}">打开对应计算 →</a>${c.links.filter(([,url])=>url!=='#atlas/notebook').map(([title,url])=>`<a href="${esc(url)}">${esc(title)} →</a>`).join('')}<a href="#atlas/notebook">研究记录 →</a></div></article>`;}).join('')}</div>`;}
 function derive(){let step=0;const list=data.exercises.filter(e=>e.module===module.id);$('#pw-content').innerHTML=`${select('选择分步练习','exercise',list.map(e=>[e.id,(progress[e.id]?'✓ ':'')+e.title]),exercise.id)}<article class="obs-lesson"><h2>${esc(exercise.title)}</h2><p>${esc(exercise.prompt)}</p><div id="pw-steps"></div><p id="pw-progress" role="status"></p>${links()}</article>`;$('#pw-exercise').onchange=e=>{exercise=list.find(x=>x.id===e.target.value);lesson=data.lessons.find(l=>l.id===exercise.lesson);draw();sync();};function next(){const s=exercise.steps[step],el=document.createElement('section');el.className='obs-exercise-step';el.innerHTML=`<h3>第 ${step+1} / ${exercise.steps.length} 步</h3><p>${esc(s.prompt)}</p><details><summary>查看提示</summary><p>${esc(s.hint)}</p></details><div class="mr-choices">${s.choices.map((c,i)=>`<button type="button" class="secondary" data-pw-answer="${i}">${esc(c)}</button>`).join('')}</div><p class="obs-feedback" role="status"></p>`;$('#pw-steps').appendChild(el);el.querySelectorAll('[data-pw-answer]').forEach(b=>b.onclick=()=>{if(+b.dataset.pwAnswer!==s.answer){el.querySelector('.obs-feedback').textContent='再想一想：'+s.hint;return;}el.querySelector('.obs-feedback').textContent='✓ '+s.explanation;el.querySelectorAll('button').forEach(b=>b.disabled=true);step++;if(step<exercise.steps.length)next();else{progress[exercise.id]=true;try{localStorage.setItem('symmetry-lab.bridges.progress.v1',JSON.stringify(progress));}catch{}$('#pw-progress').textContent='✓ 推导完成。请到实验中改变参数，检验这个结论。';}});}next();}

 function lab(){
  $('#pw-content').innerHTML=`<section id="br-prediction-panel" class="br-predict"></section><div class="qm-lab"><form id="pw-form" class="obs-controls">${select('教学预设','preset',[['','自定义 / 当前参数'],...module.presets.map(p=>[p.id,p.title])],preset)}${controlsHTML(module,forms[module.id])}<button id="pw-run" type="submit" class="primary">计算并更新演示</button><button id="pw-cancel" type="button" class="secondary">取消计算</button><p id="pw-status" role="status">Python 在浏览器本地运行。</p></form><section id="pw-result" class="qm-results" aria-live="polite"><div class="qm-welcome"><h3>从一个预设开始</h3><p>调整参数，比较物理响应与数值校验，再把结果收录到项目作业。</p></div></section></div>${links()}`;
  const panel=$('#br-prediction-panel');
  renderPrediction(panel);
  const form=$('#pw-form');form.onsubmit=e=>{e.preventDefault();calculate();};
  form.oninput=e=>{if(e.target.id==='pw-preset')return;invalidate();
   prediction=null;predicted=-1;predictionReport=null;renderPrediction(panel);try{forms[module.id]=readControls(module,root,forms[module.id]);}catch{}preset='';$('#pw-preset').value='';if(e.target.id==='pw-experiment')draw();
  };
  $('#pw-preset').onchange=e=>{invalidate();prediction=null;predicted=-1;predictionReport=null;applyPreset(e.target.value);draw();sync();};
  $('#pw-cancel').onclick=()=>{invalidate('计算已取消，可以修改参数后重新运行。');renderPrediction(panel);$('#pw-status').textContent='已取消';};
  if(result)renderResult();
 }
 function renderPrediction(panel){
  panel.innerHTML=`<h3>先预测，再计算验证</h3><p>选择一个受控预设，提交判断后运行计算。普通实验可直接运行；修改参数会退出当前预测题。</p><label>预测题<select id="br-prediction-select"><option value="">普通探索</option>${(module.predictions||[]).map(p=>`<option value="${esc(p.id)}" ${prediction?.id===p.id?'selected':''}>${esc(p.question)}</option>`).join('')}</select></label>${prediction?`<p>${esc(prediction.question)}</p><div>${prediction.choices.map((c,i)=>`<button class="secondary" type="button" data-br-predict="${i}" data-selected="${predicted===i}" ${predictionReport?'disabled':''}>${esc(c)}</button>`).join('')}</div><p id="br-prediction-feedback" role="status">${predictionReport?esc((predictionReport.correct?'预测与结论一致。':'这次预测需要修正。')+prediction.explanation):predicted>=0?'预测已记录。现在点击计算，用真实结果验证。':'先选择你的预测，答案在计算完成后显示。'}</p>${predictionReport?table(['本次计算证据','数值'],result.summary.map(s=>[s.label,num(s.value)+(s.unit?' '+s.unit:'')])):''}`:''}`;
  $('#br-prediction-select').onchange=e=>{invalidate();prediction=(module.predictions||[]).find(p=>p.id===e.target.value)||null;predicted=-1;predictionReport=null;if(prediction)applyPreset(prediction.preset);draw();sync();};
  panel.querySelectorAll('[data-br-predict]').forEach(b=>b.onclick=()=>{if(predictionReport)return;predicted=Number(b.dataset.brPredict);predictionTime=new Date().toISOString();renderPrediction(panel);});
  if($('#pw-run'))$('#pw-run').disabled=busy||!!prediction&&predicted<0;
 }
 async function calculate(){if(busy)return;if(prediction&&predicted<0){$('#pw-status').textContent='请先记录预测，再运行验证。';return;}let input;
  try{input=structuredClone(readControls(module,root,forms[module.id]));forms[module.id]=structuredClone(input);}catch(e){$('#pw-result').textContent=e.message;return;}
  const id=++ticket;busy=true;result=null;lastResult=null;$('#pw-run').disabled=true;$('#pw-status').textContent='正在计算…';$('#pw-result').innerHTML='<p role="status">正在运行 Python 并检查数值结果…</p>';
  try{const output=await run(module.action,input);if(!current()||id!==ticket||tab!=='lab')return;result=output;
   if(prediction){predictionReport={id:prediction.id,question:prediction.question,choice:prediction.choices[predicted],correct:predicted===prediction.answer,predictedAt:predictionTime,verifiedAt:new Date().toISOString(),explanation:prediction.explanation};output.learningEvidence=structuredClone(predictionReport);try{const saved=JSON.parse(localStorage.getItem('symmetry-lab.bridges.predictions.v1')||'{}');if(object(saved)){saved[prediction.id]=predictionReport;localStorage.setItem('symmetry-lab.bridges.predictions.v1',JSON.stringify(saved));}}catch{}}
   lastResult={module:module.id,input:structuredClone(input),result:output};
   const route=selection.calculationOnly?'compute/'+module.route+(context()?'?'+context():''):bridgesCourseRoute(module.id).slice(1);captureCalculation(module.action,input,output,{route,title:module.title,material:selection.material||''});
   $('#pw-status').textContent='计算完成 · 可导出或收录到项目作业';renderResult();const panel=$('#br-prediction-panel');if(panel)renderPrediction(panel);
  }catch(e){if(current()&&id===ticket){$('#pw-result').textContent=e.message;$('#pw-status').textContent='计算未完成，请检查参数';}}
  finally{if(current()&&id===ticket){busy=false;if($('#pw-run'))$('#pw-run').disabled=false;}}
 }
 function renderResult(){$('#pw-result').innerHTML=`<div class="qm-result-heading"><span class="tag">浏览器 Python 结果</span><button id="pw-export" type="button" class="secondary">导出完整 JSON</button></div>${resultHTML(module.id,result)}<a href="#atlas/projects?module=${module.id}">收录计算到跨模块项目 →</a>`;bindResult(module.id,result,root);$('#pw-export').onclick=()=>download?.(JSON.stringify(lastResult,null,2),module.id+'-result.json','application/json');}
 draw();
}
